## 3. Read data from file and calculate average

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define FILENAME "data.csv"

int main(int argc, char *argv[]) {
    // open file
    FILE *fp = fopen(FILENAME, "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    // read file
    char line[100];
    float sum = 0;
    int count = 0;
    while (fgets(line, 100, fp)!= NULL) {
        // split line into 3 values
        char *a_str = strtok(line, ",");
        char *b_str = strtok(NULL, ",");
        char *c_str = strtok(NULL, ",");

        // convert to floats
        float a = (float)atof(a_str);
        float b = (float)atof(b_str);
        float c = (float)atof(c_str);

        // add to sum
        sum += (a + b + c) / 3;
