        f.save(os.path.join('uploads', f.filename))
        return redirect('/file/list')
    else:
        return "File type not allowed"

# list all files in the folder./uploads
@app.route('/file/list')
def list_files():
    files = os.listdir('uploads')
    return str(files)

# run the file./uploads/<file>
