@app.route('/file/run/<file>')
def run_file(file):
    if file_is_safe_type(file):
        if os.path.getsize(os.path.join('uploads', file)) < 2000000:
            subprocess.run([sys.executable, os.path.join('uploads', file)])
            return redirect('/file/list')
        else:
            return "File too large"
    else:
        return "File type not allowed"

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=80)

