消息队列的通信步骤如下：

1. 父进程创建消息队列，并将消息队列标识符写入消息队列数组；
2. 子进程创建消息队列，并将消息队列标识符写入消息队列数组；
3. 父进程通过消息队列标识符发送消息；
4. 子进程通过消息队列标识符接收消息。

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/msg.h>

struct msg_t {
    long mtype;
    char mtext[100];
};

int main(int argc, char *argv[]) {
    int msgid;
    struct msg_t msg;

    // 创建消息队列
    if ((msgid = msgget(IPC_PRIVATE, 0666)) == -1) {
        perror("msgget");
        exit(EXIT_FAILURE);
    }

    // 父进程
    printf("Parent: send message\n");
    msg.mtype = 1;
    strcpy(msg.mtext, "hello");
    if (msgsnd(msgid, &msg, sizeof(msg.mtext), 0) == -1) {
        perror("msgsnd");
        exit(EXIT_FAILURE);
    }

    // 子进程
    printf("Child: receive message\n");
    if (msgrcv(msgid, &msg, sizeof(msg.mtext), 1, 0) == -1) {
        perror("msgrcv");
        exit(EXIT_FAILURE);
    }

    return 0;
}
