#include <unistd.h>
#include <sys/stat.h>

int main(int argc, char *argv[]) {
    // get a directory name from the command line
    char *dirname = argv[1];

    // get the directory's permission
    struct stat statbuf;
    int ret = stat(dirname, &statbuf);
    if (ret < 0) {
        printf("Failed to get the permission of directory %s\n", dirname);
        return -1;
    }

    // print the permission
    printf("The permission of directory %s is %o\n", dirname, statbuf.st_mode);

    return 0;
}
