## 3. Write a program that allocates a buffer of 1000 bytes and fills it with random bytes. Then write a program that allocates a buffer of 1000 bytes and fills it with random bytes. Then compare the contents of the two buffers.

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

int main(int argc, char *argv[]) {
    // get buffer size from argv
    int buffer_size = atoi(argv[1]);
    // allocate buffer
    char *buffer1 = (char *)malloc(buffer_size);
    // fill buffer with random bytes
    srand(time(NULL));
    for (int i = 0; i < buffer_size; i++) {
        buffer1[i] = rand() % 256;
    }
    // allocate buffer
    char *buffer2 = (char *)malloc(buffer_size);
    // fill buffer with random bytes
    srand(time(NULL));
    for (int i = 0; i < buffer_size; i++) {
        buffer2[i] = rand() % 256;
    }
    // compare contents of buffers
    for (int i = 0; i < buffer_size; i++) {
        if (buffer1[i]!= buffer2[i]) {
            printf("Buffers are not equal\n");
            return 1;
        }
    }
    printf("Buffers are equal\n");
    return 0;
}
