## Exercise 4

Write a program that reads a file and prints the number of words in the file.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    FILE* file = fopen(argv[1], "r");

    if (file == NULL) {
        printf("Could not open file\n");
        return 1;
    }

    int word_count = 0;
    char buffer[256];
    while (fgets(buffer, 256, file)!= NULL) {
        char* token = strtok(buffer, " ");
        while (token!= NULL) {
            word_count++;
